// הגדרת צומת בעץ
class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

// פעולה רקורסיבית המחזירה סכום כל הצמתים
int sumTree(TreeNode root) {
    // בסיס הרקורסיה: עץ ריק → סכום 0
    if (root == null) return 0;

    // סכום = ערך השורש + סכום תת-עץ שמאל + סכום תת-עץ ימין
    return root.val
         + sumTree(root.left)
         + sumTree(root.right);
}

// دالة رقرسيبية لمجموع العقد
int sumTree(TreeNode root) {
    if (root == null) return 0;
    return root.val
         + sumTree(root.left)
         + sumTree(root.right);
}










