            public static Queue<int> QueueCopy(Queue<int> que)
            {
                int x;
                Queue<int> tmp = new Queue<int>();
                Queue<int> tmpQue = new Queue<int>();
                while (!que.IsEmpty())
                {
                    x = que.Remove();
                    tmp.Insert(x);
                }

                while (!tmp.IsEmpty())
                {
                    x = tmp.Remove();
                    tmpQue.Insert(x);
                    que.Insert(x);
                }
                return tmpQue;
